  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val RequestLifecycle_eligibilitySupervisionProcess_requestLifecycle_id = Arch.ForestObservationEligibilitySupervisor_Instance_eligibilitySupervisionProcess_requestLifecycle.id
