    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case RequestLifecycle_eligibilitySupervisionProcess_requestLifecycle_id =>
          val prefix = "RequestLifecycle_eligibilitySupervisionProcess_requestLifecycle_RM_TestSuite"
          val path = testRoot /+ ISZ("forest_observation_eligibility_supervisor","Forest_Observation_Eligibility_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package forest_observation_eligibility_supervisor.Forest_Observation_Eligibility_Supervisor
                |
                |import org.sireum._
                |import forest_observation_eligibility_supervisor.Forest_Observation_Eligibility_Supervisor._
                |
                |class ${suiteName} extends RequestLifecycle_eligibilitySupervisionProcess_requestLifecycle_GumboX_TestHarness_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case EnergyAssessor_eligibilitySupervisionProcess_energyAssessor_id =>
          val prefix = "EnergyAssessor_eligibilitySupervisionProcess_energyAssessor_RM_TestSuite"
          val path = testRoot /+ ISZ("forest_observation_eligibility_supervisor","Forest_Observation_Eligibility_Supervisor")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package forest_observation_eligibility_supervisor.Forest_Observation_Eligibility_Supervisor
