  def getUpdates(bridge_id: art.Art.BridgeId, observationKind: ObservationKind.Type, container: art.DataContent): Map[String, String] = {
    observationKind match {
      case forest_observation_eligibility_supervisor.runtimemonitor.ObservationKind.ForestObservationEligibilitySupervisor_Instance_eligibilitySupervisionProcess_requestLifecycle_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[forest_observation_eligibility_supervisor.Forest_Observation_Eligibility_Supervisor.RequestLifecycle_eligibilitySupervisionProcess_requestLifecycle_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_requestState" ~> postContainer.requestState.string
        updates = updates + s"${bridge_id}_Out_lastAcceptedToken" ~> postContainer.lastAcceptedToken.string
        updates = updates + s"${bridge_id}_Out_energyTicket" ~> postContainer.api_energyTicket.string
        updates = updates + s"${bridge_id}_Out_supportTicket" ~> postContainer.api_supportTicket.string
        updates = updates + s"${bridge_id}_Out_requestContext" ~> postContainer.api_requestContext.string
        updates = updates + s"${bridge_id}_Out_eligibilityStatus" ~> postContainer.api_eligibilityStatus.string
        return updates
      case forest_observation_eligibility_supervisor.runtimemonitor.ObservationKind.ForestObservationEligibilitySupervisor_Instance_eligibilitySupervisionProcess_energyAssessor_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[forest_observation_eligibility_supervisor.Forest_Observation_Eligibility_Supervisor.EnergyAssessor_eligibilitySupervisionProcess_energyAssessor_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_energyVerdictOut" ~> postContainer.api_energyVerdictOut.string
        return updates
      case forest_observation_eligibility_supervisor.runtimemonitor.ObservationKind.ForestObservationEligibilitySupervisor_Instance_eligibilitySupervisionProcess_observationSupportAssessor_postInit =>
        var updates: Map[String, String] = Map.empty
