        return updates
      case forest_observation_eligibility_supervisor.runtimemonitor.ObservationKind.ForestObservationEligibilitySupervisor_Instance_eligibilitySupervisionProcess_authorizationGate_postInit =>
        var updates: Map[String, String] = Map.empty
