        updates = updates + s"${bridge_id}_Out_observationAuthorization" ~> postContainer.api_observationAuthorization.string
        return updates
      case forest_observation_eligibility_supervisor.runtimemonitor.ObservationKind.ForestObservationEligibilitySupervisor_Instance_eligibilitySupervisionProcess_requestLifecycle_preCompute =>
        var updates: Map[String, String] = Map.empty
